/**
 * Ensures the admin user also exists in Firebase Authentication (Users tab in console).
 */
async function ensureFirebaseAuthUser() {
  if (!firebaseConfig.apiKey) return;
  try {
    const res = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signUp?key=${firebaseConfig.apiKey}`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        email: INITIAL_ADMIN_EMAIL,
        password: INITIAL_ADMIN_SEED_PASSWORD,
        returnSecureToken: true
      })
    });
    const data: any = await res.json().catch(() => ({}));
    if (res.ok) {
      console.log(`[Firebase Auth] Successfully registered admin in Firebase Authentication: ${INITIAL_ADMIN_EMAIL}`);
    } else if (data.error?.message?.includes("EMAIL_EXISTS")) {
      console.log(`[Firebase Auth] Admin already registered in Firebase Authentication: ${INITIAL_ADMIN_EMAIL}`);
    } else {
      console.log(`[Firebase Auth] Notice on Firebase Auth signup:`, data?.error?.message || data);
    }
  } catch (err) {
    console.error("[Firebase Auth] Error registering admin in Firebase Auth:", err);
  }
}

/**
 * Ensures the initial admin user exists in the Firestore 'admin_users' collection.
 * The password is ALWAYS stored as a secure bcrypt hash, never plain text.
 */
async function ensureInitialAdminUser() {
  try {
    // Check if the primary admin user document exists in admin_users
    const adminDocRef = doc(db, "admin_users", INITIAL_ADMIN_EMAIL);
    const adminSnap = await getDoc(adminDocRef);

    if (!adminSnap.exists()) {
      // Also query if any admin user with this email exists by query
      const usersCol = collection(db, "admin_users");
      const q = query(usersCol, where("email", "==", INITIAL_ADMIN_EMAIL));
      const existingByEmail = await getDocs(q);

      if (existingByEmail.empty) {
        // Hash the initial password with bcrypt (10 rounds)
        const passwordHash = bcrypt.hashSync(INITIAL_ADMIN_SEED_PASSWORD, 10);
        const newAdminDoc = {
          email: INITIAL_ADMIN_EMAIL,
          passwordHash: passwordHash,
          role: "admin",
          createdAt: new Date().toISOString()
        };

        await setDoc(adminDocRef, newAdminDoc);
        console.log(`[Auth] Initial admin account created in Firestore admin_users collection for: ${INITIAL_ADMIN_EMAIL}`);
      }
    }

    // Also ensure registration in Firebase Auth
    await ensureFirebaseAuthUser();
  } catch (err) {
    console.error("[Auth] Error verifying/creating initial admin in Firestore:", err);
  }
}

/**
 * Finds an admin user by email or login identifier from Firestore 'admin_users' collection
 */
async function findAdminUser(identifier: string) {
  const clean = identifier.trim().toLowerCase();

  try {
    // 1. Direct document lookup by ID (email)
    const directRef = doc(db, "admin_users", clean);
    const directSnap = await getDoc(directRef);
    if (directSnap.exists()) {
      return { id: directSnap.id, ...(directSnap.data() as any) };
    }

    // 2. Lookup by email field
    const usersCol = collection(db, "admin_users");
    const q = query(usersCol, where("email", "==", clean));
    const snap = await getDocs(q);
    if (!snap.empty) {
      const firstDoc = snap.docs[0];
      return { id: firstDoc.id, ...firstDoc.data() };
    }

    // 3. Fallback alias for 'admin' username mapping to default admin email
    if (clean === "admin") {
      const defaultAdminRef = doc(db, "admin_users", INITIAL_ADMIN_EMAIL);
      const defaultSnap = await getDoc(defaultAdminRef);
      if (defaultSnap.exists()) {
        return { id: defaultSnap.id, ...(defaultSnap.data() as any) };
      }
    }
  } catch (err) {
    console.error("[Auth] Error querying admin user from Firestore:", err);
  }

  return null;
}

// Middleware to verify JWT tokens
function authenticateToken(req: any, res: any, next: any) {
  const authHeader = req.headers["authorization"];
  const token = authHeader && authHeader.split(" ")[1];

  if (!token) {
    return res.status(401).json({ error: "Access token required" });
  }

  jwt.verify(token, JWT_SECRET, (err: any, user: any) => {
    if (err) {
      return res.status(403).json({ error: "Invalid or expired token" });
    }
    req.user = user;
    next();
  });
}

