// Secure Admin Login
app.post("/api/admin/login", async (req, res) => {
  try {
    const { username, password } = req.body || {};

    if (!username || !password || typeof username !== "string" || typeof password !== "string") {
      return res.status(400).json({ error: "Username/Email and Password are required." });
    }

    // Ensure initial admin account exists in Firestore if not yet initialized
    await ensureInitialAdminUser();

    // Query admin user in Firestore 'admin_users' collection
    const adminUser = await findAdminUser(username);

    if (!adminUser) {
      return res.status(401).json({ error: "Invalid username or password. Please check your credentials." });
    }

    const storedHash = adminUser.passwordHash || adminUser.password_hash;
    if (!storedHash || typeof storedHash !== "string") {
      return res.status(401).json({ error: "Invalid admin account configuration in database." });
    }

    // Verify submitted password against stored bcrypt hash
    const isPasswordValid = bcrypt.compareSync(password.trim(), storedHash);
    if (!isPasswordValid) {
      return res.status(401).json({ error: "Invalid username or password. Please check your credentials." });
    }

    // Generate secure JWT token
    const token = jwt.sign(
      { 
        email: adminUser.email,
        username: adminUser.email, 
        role: adminUser.role || "admin" 
      }, 
      JWT_SECRET, 
      { expiresIn: "24h" }
    );

    // Return success (never expose password or passwordHash)
    return res.status(200).json({ 
      success: true, 
      token, 
      username: adminUser.email 
    });
  } catch (error: any) {
    console.error("Admin login error:", error);
    return res.status(500).json({ error: "Login process failed. Please try again." });
  }
});

// Admin: Change Permanent Password / Username in Firestore
app.post("/api/admin/change-password", authenticateToken, async (req, res) => {
  try {
    const { newUsername, newPassword, currentPassword } = req.body || {};

    if (!newPassword || typeof newPassword !== "string" || newPassword.trim().length < 6) {
      return res.status(400).json({ error: "New password must be at least 6 characters long." });
    }

    const currentEmail = (req as any).user?.email || (req as any).user?.username || INITIAL_ADMIN_EMAIL;
    const adminUser = await findAdminUser(currentEmail);

    if (!adminUser) {
      return res.status(404).json({ error: "Admin user not found in database." });
    }

    // If current password provided, verify it first
    if (currentPassword) {
      const storedHash = adminUser.passwordHash || adminUser.password_hash;
      if (!bcrypt.compareSync(currentPassword.trim(), storedHash)) {
        return res.status(401).json({ error: "Current password does not match." });
      }
    }

    const updatedEmail = (newUsername && typeof newUsername === "string" && newUsername.trim()) 
      ? newUsername.trim().toLowerCase() 
      : adminUser.email;
    const updatedHash = bcrypt.hashSync(newPassword.trim(), 10);

    const targetDocId = adminUser.id || adminUser.email || INITIAL_ADMIN_EMAIL;
    const userDocRef = doc(db, "admin_users", targetDocId);
    
    const updatedData = {
      email: updatedEmail,
      passwordHash: updatedHash,
      role: "admin",
      updatedAt: new Date().toISOString()
    };

    await setDoc(userDocRef, updatedData, { merge: true });

    return res.json({ 
      success: true, 
      message: "Admin credentials updated and saved permanently in Firestore admin_users! ❤️",
      username: updatedEmail
    });
  } catch (error) {
    console.error("Error updating admin credentials:", error);
    return res.status(500).json({ error: "Failed to update admin credentials." });
  }
});

// Get all responses with Stats
app.get("/api/admin/responses", authenticateToken, async (req, res) => {
  try {
    const responsesCol = collection(db, "responses");
    // Sort by default on client or server - fetch all first
    const q = query(responsesCol);
    const querySnapshot = await getDocs(q);
    
    const responses: any[] = [];
    querySnapshot.forEach((doc) => {
      const data = doc.data();
      responses.push({
        id: doc.id,
        ...data
      });
    });

    // Sort responses by created_at desc (newest first)
    responses.sort((a, b) => {
      const dateA = new Date(a.created_at || 0).getTime();
      const dateB = new Date(b.created_at || 0).getTime();
      return dateB - dateA;
    });

    return res.json({ responses });
  } catch (error) {
    console.error("Error fetching responses: ", error);
    return res.status(500).json({ error: "Failed to fetch responses from database." });
  }
});

// Delete individual response
app.delete("/api/admin/responses/:id", authenticateToken, async (req, res) => {
  try {
    const { id } = req.params;
    const responseRef = doc(db, "responses", id);

    // Verify if the document exists before deleting
    const responseSnap = await getDoc(responseRef);
    if (!responseSnap.exists()) {
      return res.status(404).json({ error: "Response not found." });
    }

    await deleteDoc(responseRef);
    return res.json({ success: true, message: "Response deleted successfully." });
  } catch (error) {
    console.error("Error deleting response: ", error);
    return res.status(500).json({ error: "Failed to delete response." });
  }
});

// Get real-time stats and voting ranking
app.get("/api/admin/stats", authenticateToken, async (req, res) => {
  try {
    const responsesCol = collection(db, "responses");
    const querySnapshot = await getDocs(responsesCol);

    let total = 0;
    let going = 0;
    let notGoing = 0;
    const locationVotes: { [key: string]: number } = {};

    querySnapshot.forEach((doc) => {
      const data = doc.data();
      total++;
      if (data.joining_status === "Yes") {
        going++;
      } else if (data.joining_status === "No") {
        notGoing++;
      }

      const loc = data.location ? data.location.trim() : "";
      if (loc) {
        // Normalize location capitalization for better counting
        const key = loc;
        locationVotes[key] = (locationVotes[key] || 0) + 1;
      }
    });

    // Create sorted popular locations list
    const popularLocations = Object.entries(locationVotes)
      .map(([name, votes]) => ({ name, votes }))
      .sort((a, b) => b.votes - a.votes);

    return res.json({
      totalResponses: total,
      going,
      notGoing,
      locationsCount: Object.keys(locationVotes).length,
      popularLocations
    });
  } catch (error) {
    console.error("Error fetching stats: ", error);
    return res.status(500).json({ error: "Failed to compute stats." });
  }
});

